import json, math

def opts(t, s):
    e = math.exp
    return {
        1: (3*t*(e(s)-1), t/2*(e(-s)+1), t*t*e(-2*s)),
        2: (2*t*(e(s)-1), t*(2*e(2*s)-1), t*t/2*(1+e(-2*s))),
        3: (2*t*(e(s)-1), t/2*(e(s)+1), t*t*e(2*s)),
        4: (t*(e(-s)-1), -2*t*(e(-s)-1.5), t*t*(2*e(-2*s)-1)),
    }

h = 1e-5
ok = {}
for k in range(1, 5):
    good = True
    for t in (0.7, 1.3, -2.0):
        # initial condition at s=0: x=0, y=t, u=t^2
        x0, y0, u0 = opts(t, 0.0)[k]
        if abs(x0) > 1e-9 or abs(y0 - t) > 1e-9 or abs(u0 - t*t) > 1e-9:
            good = False
        for s in (0.0, 0.3, 0.8):
            a = opts(t, s+h)[k]
            b = opts(t, s-h)[k]
            c = opts(t, s)[k]
            dx = (a[0]-b[0])/(2*h)   # = F_p = q
            dy = (a[1]-b[1])/(2*h)   # = F_q = p
            du = (a[2]-b[2])/(2*h)   # = 2pq
            q, p, u = dx, dy, c[2]
            if abs(p*q - u) > 1e-5*(1+abs(u)):
                good = False
            if abs(du - 2*p*q) > 1e-5*(1+abs(u)):
                good = False
    ok[k] = good

answer = [k for k, v in ok.items() if v]
if len(answer) == 1:
    final = "Option %d" % answer[0]
else:
    final = "UNSUPPORTED"
print(json.dumps({"final_answer": final, "evidence": {"checks": ok,
      "derivation": "p0=tau/2,q0=2tau; x'=q,y'=p,u'=2u,p'=p,q'=q"}}))
