import json, itertools

cats = {
 "opinion": "silly terrible wonderful lovely repulsive ridiculous nice awful good mysterious",
 "size": "medium-size massive little huge large tiny big small enormous midsize normal-size",
 "age": "new archaic old-fashioned ancient brand-new old",
 "shape": "prismlike rectangular square pyramidal circular triangular spherical",
 "color": "yellow violet aqua crimson brown maroon magenta cyan pink blue indigo red gray green white black",
 "origin": "egyptian chinese turkish vietnamese german bangladeshi mexican iranian ethiopian russian filipino thai indonesian",
 "material": "plastic wood wool iron fiberglass cardboard glass leather paper cloth",
 "purpose": "typing whittling walking smoking hiking drinking snorkeling driving eating exercise",
}
lex = {}
for c, ws in cats.items():
    for w in ws.split():
        lex[w] = c

multi = {("flower", "pot"), ("car", "key"), ("trash", "can"), ("fire", "extinguisher")}

def parse(s):
    t = s.split()
    if len(t) >= 2 and (t[-2], t[-1]) in multi:
        t = t[:-2]
    else:
        t = t[:-1]
    out = []
    for w in t:
        if w not in lex:
            raise ValueError("unknown word " + w)
        out.append(lex[w])
    return out

data = """yellow ruler|silly violet fork|silly aqua key|prismlike sunglasses|new ruler|archaic apple|terrible stapler|crimson dog|medium-size spoon|old-fashioned hammer|prismlike pen|typing ruler|new guitar|plastic egyptian necklace|wonderful shoe|whittling ruler|lovely piano|new scissors|whittling saw|lovely aqua necklace|massive spoon|ancient exercise candle|silly brown jar|rectangular stapler|prismlike bird|walking car|wood chinese hat|smoking apple|little square plate|old-fashioned typing flower pot|repulsive canvas|hiking hat|wool speaker|turkish old green box|huge dog|pyramidal lamp|prismlike saw|circular flower pot|maroon chair|egyptian jar|magenta bird|hiking spoon|iron sofa|large hat|tiny speaker|fiberglass vietnamese bottle|cyan hat|old-fashioned car key|new smoking toolbox|big triangular earring|terrible hat|maroon piano|ridiculous indigo sunglasses|archaic snorkeling bicycle|cardboard sofa|lovely fork|circular bowl|pink guitar|medium-size car|large fork|blue candle|triangular plate|rectangular spoon|huge scissors|massive knife|small circular pencil|small spherical key|ancient drinking candle|new drill|new drinking bowl|triangular sunglasses|brand-new cup|mysterious hammer|enormous triangular calculator|whittling stapler|square bed|cardboard typing lovely flower pot|german piano|glass bangladeshi watch|wool hammer|triangular house|iron mexican vase|massive rectangular screwdriver|prismlike necklace|nice red flower pot|old-fashioned pen|awful magenta spoon|russian bird|crimson flower pot|tiny pyramidal vase|good key|leather iranian box|repulsive gray ring|ethiopian knife|brown bag|midsize circular chair|snorkeling trash can|new whittling fire extinguisher""".split("|")

opts = {
"A": "circular large old-fashioned driving good black sofa",
"B": "wood filipino ancient smoking awful violet tiny prismlike fork",
"C": "prismlike brand-new smoking ridiculous violet iranian paper bed",
"D": "old drinking terrible white normal-size square wrench",
"E": "cloth thai brand-new eating good blue plate",
"F": "fiberglass indonesian brand-new smoking wonderful cyan massive bottle",
"G": "big rectangular archaic smoking terrible yellow vase",
"H": "thai old drinking nice green massive pyramidal clock",
"I": "glass bangladeshi old-fashioned snorkeling nice magenta prismlike canvas",
"J": "spherical little ancient walking good indigo bangladeshi jar",
}

def main():
    cons = set()
    for s in data:
        seq = parse(s)
        for i in range(len(seq)):
            for j in range(i + 1, len(seq)):
                if seq[i] != seq[j]:
                    cons.add((seq[i], seq[j]))
    names = list(cats.keys())
    orders = []
    for p in itertools.permutations(names):
        pos = {c: i for i, c in enumerate(p)}
        if all(pos[a] < pos[b] for a, b in cons):
            orders.append(pos)
    if not orders:
        print("UNSUPPORTED")
        return
    parsed = {k: parse(v) for k, v in opts.items()}
    result = {}
    for k, seq in parsed.items():
        vals = set()
        for pos in orders:
            ok = all(pos[seq[i]] < pos[seq[i + 1]] for i in range(len(seq) - 1))
            vals.add(ok)
        if len(vals) > 1:
            print("UNSUPPORTED")
            return
        result[k] = vals.pop()
    ans = "".join(k for k in sorted(result) if result[k])
    if not ans:
        ans = "K"
    print(json.dumps({
        "final_answer": ans,
        "evidence": {
            "consistent_orders": len(orders),
            "constraints": sorted("%s<%s" % c for c in cons),
            "option_valid": result,
        }
    }))

main()
