cats = {
 'opinion': "silly terrible wonderful lovely repulsive ridiculous awful nice good mysterious",
 'size': "medium-size massive little huge large tiny big small enormous midsize normal-size",
 'age': "new archaic old-fashioned ancient brand-new old",
 'shape': "prismlike rectangular square pyramidal circular triangular spherical",
 'color': "yellow violet aqua crimson brown green maroon magenta cyan pink blue indigo red gray white black",
 'origin': "egyptian chinese turkish vietnamese german bangladeshi mexican iranian russian ethiopian filipino indonesian thai",
 'material': "plastic wood wool iron fiberglass cardboard glass leather cloth paper",
 'purpose': "typing whittling exercise drinking walking smoking hiking snorkeling eating driving",
}
w2c = {}
for c, ws in cats.items():
    for w in ws.split():
        w2c[w] = c

data = """silly violet fork|silly aqua key|plastic egyptian necklace|lovely aqua necklace|ancient exercise candle|silly brown jar|wood chinese hat|little square plate|old-fashioned typing flower pot|turkish old green box|fiberglass vietnamese bottle|new smoking toolbox|big triangular earring|ridiculous indigo sunglasses|archaic snorkeling bicycle|small circular pencil|small spherical key|ancient drinking candle|new drinking bowl|enormous triangular calculator|cardboard typing lovely flower pot|glass bangladeshi watch|iron mexican vase|massive rectangular screwdriver|nice red flower pot|awful magenta spoon|tiny pyramidal vase|leather iranian box|repulsive gray ring|midsize circular chair|new whittling fire extinguisher|new smoking toolbox"""

def cat_seq(s):
    toks = s.split()
    seq = []
    for t in toks:
        if t in w2c:
            seq.append(w2c[t])
    return seq

edges = set()
for s in data.split('|'):
    seq = cat_seq(s)
    for i in range(len(seq)):
        for j in range(i+1, len(seq)):
            if seq[i] != seq[j]:
                edges.add((seq[i], seq[j]))

names = list(cats)
reach = {(a, b) for a, b in edges}
changed = True
while changed:
    changed = False
    for (a, b) in list(reach):
        for (c, d) in list(reach):
            if b == c and (a, d) not in reach:
                reach.add((a, d)); changed = True
cyc = [c for c in names if (c, c) in reach]
print("cycles:", cyc)

opts = {
'A': "circular large old-fashioned driving good black sofa",
'B': "wood filipino ancient smoking awful violet tiny prismlike fork",
'C': "prismlike brand-new smoking ridiculous violet iranian paper bed",
'D': "old drinking terrible white normal-size square wrench",
'E': "cloth thai brand-new eating good blue plate",
'F': "fiberglass indonesian brand-new smoking wonderful cyan massive bottle",
'G': "big rectangular archaic smoking terrible yellow vase",
'H': "thai old drinking nice green massive pyramidal clock",
'I': "glass bangladeshi old-fashioned snorkeling nice magenta prismlike canvas",
'J': "spherical little ancient walking good indigo bangladeshi jar",
}
determined_ok = []
undetermined = []
for k, s in opts.items():
    toks = s.split()
    unk = [t for t in toks[:-1] if t not in w2c]
    seq = cat_seq(" ".join(toks[:-1]))
    viol = []
    unc = []
    for i in range(len(seq)-1):
        a, b = seq[i], seq[i+1]
        for x in range(i, i+1):
            pass
    for i in range(len(seq)):
        for j in range(i+1, len(seq)):
            a, b = seq[i], seq[j]
            if a == b:
                continue
            if (b, a) in reach:
                viol.append((a, b))
            elif (a, b) not in reach:
                unc.append((a, b))
    status = "VIOLATES" if viol else ("UNDETERMINED" if unc else "CORRECT")
    print(k, seq, status, "viol=", viol, "unknown=", unc, "unk_tokens=", unk)
    if status == "CORRECT":
        determined_ok.append(k)
    elif status == "UNDETERMINED":
        undetermined.append(k)

print("determined correct:", determined_ok)
print("undetermined by data:", undetermined)
submitted = "K"
if determined_ok:
    print("Submitted K claims none correct, but", determined_ok, "is/are correct")
    print("CHECK FAIL")
elif undetermined:
    print("CHECK UNKNOWN")
else:
    print("CHECK PASS")
