import json, math, re, sys

path = """M 24.38698,-19.9365 L 29.3405,-17.62663 M 0.0,7.0 L 0.0,5.46 M 10.35209,0.0 L 10.35209,-7.0986 M 20.49493,-28.84999 L 17.75636,-22.97711 M 20.49493,-21.75139 L 24.38698,-19.9365 M 18.29129,-17.02568 L 20.49493,-21.75139 M 17.75636,-22.97711 L 15.16487,-17.41963 M 10.35209,-7.0986 L 0.0,-7.0986 M 22.10067,8.68911 L 19.34832,10.61633 M 2.5205,-5.64339 L 6.14757,-3.5493 M 10.35209,-4.68508 L 10.35209,0.0 M 10.35209,-7.0986 L 10.35209,-4.68508 M 20.49493,-25.44266 L 20.49493,-28.84999 M 0.0,-7.0986 L 2.5205,-5.64339 M 6.14757,-3.5493 L 2.33608,-1.34873 M 24.85302,6.76189 L 22.10067,8.68911 M 15.93065,-11.96326 L 17.25429,-14.80182 M 20.49493,-21.75139 L 20.49493,-25.44266 M 19.34832,10.61633 L 17.21983,12.10671 L 11.74658,15.93912 M 10.35209,1.96 L 10.35209,3.3712 M 0.0,5.46 L 0.0,0.0 M 4.03732,0.0 L 10.35209,0.0 M 10.35209,7.0 L 7.55703,7.0 M 10.35209,0.0 L 15.93065,-11.96326 M 10.35209,3.3712 L 10.35209,7.0 M 2.33608,-1.34873 L 0.0,0.0 M 34.99586,-14.98949 L 24.85302,6.76189 M 15.16487,-17.41963 L 10.35209,-7.0986 M 11.74658,15.93912 L 11.17484,9.40408 M 0.0,0.0 L 4.03732,0.0 M 11.17484,9.40408 L 10.79637,5.0782 M 29.3405,-17.62663 L 34.99586,-14.98949 M 10.35209,0.0 L 10.35209,1.96 M 10.79637,5.0782 L 10.35209,0.0 M 7.55703,7.0 L 0.0,7.0 M 17.25429,-14.80182 L 18.29129,-17.02568"""

# parse into segments (polyline chains with M/L)
toks = re.findall(r'([MLml])\s*(-?\d+\.?\d*)\s*,\s*(-?\d+\.?\d*)', path)
segs = []
cur = None
for c, x, y in toks:
    p = (round(float(x), 5), round(float(y), 5))
    if c.upper() == 'M':
        cur = p
    else:
        segs.append((cur, p))
        cur = p

nodes = set()
for a, b in segs:
    nodes.add(a); nodes.add(b)
nodes = list(nodes)

def dist_pt_seg(p, a, b):
    ax, ay = a; bx, by = b; px, py = p
    dx, dy = bx - ax, by - ay
    L2 = dx * dx + dy * dy
    if L2 == 0:
        return math.hypot(px - ax, py - ay), 0
    t = ((px - ax) * dx + (py - ay) * dy) / L2
    tc = max(0, min(1, t))
    return math.hypot(px - (ax + tc * dx), py - (ay + tc * dy)), t

edges = set()
for a, b in segs:
    pts = [(0.0, a), (1.0, b)]
    for p in nodes:
        if p == a or p == b:
            continue
        d, t = dist_pt_seg(p, a, b)
        if d < 1e-3 and 0 < t < 1:
            pts.append((t, p))
    pts.sort()
    for i in range(len(pts) - 1):
        u, v = pts[i][1], pts[i + 1][1]
        if u != v:
            edges.add(frozenset((u, v)))

adj = {}
for e in edges:
    u, v = tuple(e)
    adj.setdefault(u, set()).add(v)
    adj.setdefault(v, set()).add(u)

idx = {n: i for i, n in enumerate(sorted(adj))}
cycles = set()
LIMIT = 200000
count = 0
def dfs(start, node, visited, pathl):
    global count
    if count > LIMIT:
        return
    for nb in adj[node]:
        if nb == start and len(pathl) >= 3:
            key = frozenset(frozenset((pathl[i], pathl[(i + 1) % len(pathl)])) for i in range(len(pathl)))
            if key not in cycles:
                cycles.add(key)
                cyc_list.append(list(pathl))
            count += 1
        elif nb not in visited and idx[nb] > idx[start]:
            visited.add(nb)
            pathl.append(nb)
            dfs(start, nb, visited, pathl)
            pathl.pop()
            visited.discard(nb)

cyc_list = []
for s in adj:
    dfs(s, s, {s}, [s])

def cross(a, b): return a[0] * b[1] - a[1] * b[0]
def dot(a, b): return a[0] * b[0] + a[1] * b[1]
def norm(a): return math.hypot(*a)

def simplify(poly):
    changed = True
    while changed and len(poly) > 3:
        changed = False
        n = len(poly)
        for i in range(n):
            p, q, r = poly[i - 1], poly[i], poly[(i + 1) % n]
            v1 = (q[0] - p[0], q[1] - p[1]); v2 = (r[0] - q[0], r[1] - q[1])
            if abs(cross(v1, v2)) / (norm(v1) * norm(v2)) < 1e-3 and dot(v1, v2) > 0:
                poly = poly[:i] + poly[i + 1:]
                changed = True
                break
    return poly

def classify(poly):
    n = len(poly)
    v = [(poly[(i + 1) % n][0] - poly[i][0], poly[(i + 1) % n][1] - poly[i][1]) for i in range(n)]
    cs = [cross(v[i], v[(i + 1) % n]) / (norm(v[i]) * norm(v[(i + 1) % n])) for i in range(n)]
    convex = all(c > 1e-3 for c in cs) or all(c < -1e-3 for c in cs)
    par = lambda a, b: abs(cross(a, b)) / (norm(a) * norm(b)) < 1e-3
    if n == 3:
        for i in range(3):
            if abs(dot(v[i], v[(i + 1) % 3])) / (norm(v[i]) * norm(v[(i + 1) % 3])) < 1e-3:
                return 4
        return 3
    if n == 4:
        if not convex:
            return None
        p02, p13 = par(v[0], v[2]), par(v[1], v[3])
        if p02 and p13:
            right = abs(dot(v[0], v[1])) / (norm(v[0]) * norm(v[1])) < 1e-3
            if right:
                return 2 if abs(norm(v[0]) - norm(v[1])) / norm(v[0]) < 1e-3 else 1
            return 5
        if p02 or p13:
            return 6
        return None
    if n == 5:
        if not convex:
            return 8
        L = [norm(x) for x in v]
        ang = [dot(v[i], v[(i + 1) % n]) / (L[i] * L[(i + 1) % n]) for i in range(n)]
        if max(L) - min(L) < 1e-3 * max(L) * 3 and max(ang) - min(ang) < 3e-3:
            return 9
        return 7
    if n == 6 and convex:
        L = [norm(x) for x in v]
        ang = [dot(v[i], v[(i + 1) % n]) / (L[i] * L[(i + 1) % n]) for i in range(n)]
        if max(L) - min(L) < 3e-3 * max(L) and max(ang) - min(ang) < 3e-3:
            return 10
    return None

found = set()
for cyc in cyc_list:
    poly = simplify(cyc)
    if len(poly) < 3:
        continue
    k = classify(poly)
    if k is not None:
        found.add(k)

options = {
 'A': {1,7,3}, 'B': {1,8}, 'C': {7,9}, 'D': {5}, 'E': {1,5,7,8},
 'F': {1,5,7,8,4,6}, 'G': {7,8,2,10}, 'H': {1,8,9}, 'I': {5,3}, 'J': {1},
 'K': {7,8}, 'L': {5,8}, 'M': {5,2}, 'N': {1,8,2,4,9}, 'O': {1,5,7,8,10},
 'P': {1,7,8,6}}
match = [k for k, s in options.items() if s == found]
if len(match) == 1 and count <= LIMIT:
    print(json.dumps({"final_answer": match[0],
                      "evidence": {"shapes_found": sorted(found), "cycles": len(cyc_list), "edges": len(edges)}}))
else:
    print("UNSUPPORTED")
