# Forward-chaining derivation of the BoardgameQA problem, with the preferences handled explicitly.
# Colour convention: primary colours are red, green, blue. The frog's card is yellow, so not primary.

primary = {"red", "green", "blue"}

facts = set()
def add(f): facts.add(f)

# Initial facts
add("snake_reduced_hours")
add("frog_has_leafy_green")        # spinach is a leafy green vegetable
frog_card_primary = "yellow" in primary   # False
frog_young = None                  # unknown, so Rule11 cannot be applied
add("not_bee_tears_badger")
add("not_seahorse_creates_vampire")

# Rule 12: seahorse enjoys companionship of the ant
if "not_seahorse_creates_vampire" in facts: add("ant_companion")

# Rule 21 vs Rule 16 / Rule 11 (preferred rules need to apply to override)
rule16 = frog_card_primary
rule11 = (frog_young is True)
if "frog_has_leafy_green" in facts and not rule16 and not rule11:
    add("frog_destroys_wall")

# Rule 24 beats Rule 6
if "frog_destroys_wall" in facts: add("swan_shouts_peafowl")
elif "ant_companion" in facts: add("not_swan_shouts_peafowl")

# Rule 22 (Rule 3 preferred; nobody persuades the rhino)
rhino_persuaded = False
if "swan_shouts_peafowl" in facts and not rhino_persuaded: add("swan_shouts_beaver")

# Rule 1 (Rule 15 preferred; nobody trades with the bison)
bison_trade = False
if "swan_shouts_beaver" in facts and not bison_trade: add("swan_unites_ostrich")

# Rule 7
if "swan_unites_ostrich" in facts: add("beetle_trades_stork")

# Rule 23, Rule 2
if "snake_reduced_hours" in facts: add("snake_tears_dove")
if "snake_tears_dove" in facts: add("woodpecker_takes_monkey")

# Rule 13 (Rule 8 preferred; nobody creates a castle for the dragon)
dragon_castle = False
if "woodpecker_takes_monkey" in facts and not dragon_castle: add("bee_not_refuse_dinosaur")

# Rule 17
if "bee_not_refuse_dinosaur" in facts: add("bee_reveals_zebra")

# Rule 5, 19, 20, 14 (Rule 9 preferred, but the flamingo smiling at the bee is not established)
if "not_bee_tears_badger" in facts: add("bee_refuses_badger")
if "bee_refuses_badger" in facts: add("bee_shouts_dragonfly")
if "bee_shouts_dragonfly" in facts: add("bee_wants_fangtooth")
flamingo_smiles_bee = False
if "bee_wants_fangtooth" in facts and not flamingo_smiles_bee: add("bee_not_shout_beetle")

# Rule 18
if "bee_not_shout_beetle" in facts and "bee_reveals_zebra" in facts:
    add("bee_not_trade_stork")

# Rule 4
if "bee_not_trade_stork" in facts and "beetle_trades_stork" in facts:
    add("stork_wants_goat")

# Rule 10
if "stork_wants_goat" in facts: add("finch_not_capture_pigeon_king")

print(sorted(facts))
if "finch_not_capture_pigeon_king" in facts:
    result = "disproved"
else:
    result = "unknown"
print("derived:", result)
print("claimed: disproved")
print("CHECK PASS" if result == "disproved" else "CHECK FAIL")
