toks = path.replace(",", " ").split()
segs = []
i = 0
cur = None
prev = None
while i < len(toks):
    t = toks[i]
    if t in ("M", "L"):
        x = float(toks[i+1]); y = float(toks[i+2]); i += 3
        p = (x, y)
        if t == "L" and prev is not None:
            segs.append((prev, p))
        prev = p
    else:
        i += 1

nodes = []
def nid(p):
    for k, q in enumerate(nodes):
        if abs(p[0]-q[0]) < 1e-4 and abs(p[1]-q[1]) < 1e-4:
            return k
    nodes.append(p)
    return len(nodes)-1

segi = [(nid(a), nid(b)) for a, b in segs]

def on_seg(p, a, b):
    ax, ay = a; bx, by = b
    dx, dy = bx-ax, by-ay
    L2 = dx*dx+dy*dy
    if L2 == 0: return False
    t = ((p[0]-ax)*dx+(p[1]-ay)*dy)/L2
    if t <= 1e-6 or t >= 1-1e-6: return False
    px, py = ax+t*dx, ay+t*dy
    return math.hypot(px-p[0], py-p[1]) < 1e-4

edges = set()
for a, b in segi:
    pts = [a, b]
    for k, p in enumerate(nodes):
        if k not in (a, b) and on_seg(p, nodes[a], nodes[b]):
            pts.append(k)
    A = nodes[a]
    pts.sort(key=lambda k: (nodes[k][0]-A[0])**2+(nodes[k][1]-A[1])**2)
    for u, v in zip(pts, pts[1:]):
        if u != v:
            edges.add((min(u, v), max(u, v)))

adj = {k: set() for k in range(len(nodes))}
for u, v in edges:
    adj[u].add(v); adj[v].add(u)

cycles = []
start_time = time.time()
def dfs(s, u, pathl, visited):
    if time.time()-start_time > 3.5: return
    for w in adj[u]:
        if w == s and len(pathl) >= 3:
            if pathl[1] < pathl[-1]:
                cycles.append(list(pathl))
        elif w > s and w not in visited and len(pathl) < 14:
            visited.add(w); pathl.append(w)
            dfs(s, w, pathl, visited)
