def cross(a, b): return a[0]*b[1]-a[1]*b[0]
def dot(a, b): return a[0]*b[0]+a[1]*b[1]
def norm(a): return math.hypot(*a)

def simplify(pts):
    changed = True
    while changed and len(pts) > 3:
        changed = False
        n = len(pts)
        for k in range(n):
            a, b, c = pts[k-1], pts[k], pts[(k+1) % n]
            v1 = (b[0]-a[0], b[1]-a[1]); v2 = (c[0]-b[0], c[1]-b[1])
            if abs(cross(v1, v2)) < 1e-3*norm(v1)*norm(v2)+1e-9:
                pts = pts[:k]+pts[k+1:]
                changed = True
                break
    return pts

def classify(pts):
    n = len(pts)
    v = [(pts[(k+1) % n][0]-pts[k][0], pts[(k+1) % n][1]-pts[k][1]) for k in range(n)]
    L = [norm(x) for x in v]
    par = lambda a, b: abs(cross(a, b)) < 1e-3*norm(a)*norm(b)
    perp = lambda a, b: abs(dot(a, b)) < 1e-3*norm(a)*norm(b)
    if n == 3:
        for k in range(3):
            if perp(v[k], v[(k+1) % 3]): return 4
        return 3
    if n == 4:
        if abs(v[0][0]+v[2][0]) < 1e-3*max(L) and abs(v[0][1]+v[2][1]) < 1e-3*max(L) and \
           abs(v[1][0]+v[3][0]) < 1e-3*max(L) and abs(v[1][1]+v[3][1]) < 1e-3*max(L):
            if perp(v[0], v[1]):
                return 2 if abs(L[0]-L[1]) < 1e-3*L[0] else 1
            return 5
        p1 = par(v[0], v[2]); p2 = par(v[1], v[3])
        if p1 != p2: return 6
        return None
    if n in (5, 6):
        cs = [cross(v[k], v[(k+1) % n]) for k in range(n)]
        convex = all(c > 0 for c in cs) or all(c < 0 for c in cs)
        if convex and max(L)-min(L) < 1e-3*max(L):
            angs = [math.atan2(abs(cs[k]), dot(v[k], v[(k+1) % n])) for k in range(n)]
            if max(angs)-min(angs) < 1e-2:
                return 9 if n == 5 else 10
        if n == 5:
            return 7 if convex else 8
        return None
    return None

found = {}
for c in cycles:
    pts = simplify([nodes[k] for k in c])
    r = classify(pts)
    if r is not None:
        found.setdefault(r, []).append(c)

print("nodes", len(nodes), "edges", len(edges), "cycles", len(cycles))
