import json
from itertools import product

# Model: the explanation says "Confucius's 'not eating out of time' means not eating
# out-of-season vegetables." Its premise is that such vegetables were
# available in his era, so that the injunction is non-vacuous.
# Assumption test: negating a necessary assumption must make the explanation fail.

options = {
    "A": "Confucius is very demanding in diet",
    "B": "Confucius's era had both seasonal and out-of-season vegetables",
    "C": "We can choose seasonal or out-of-season vegetables",
    "D": "Diet nourishes the body and shapes the mind",
}

def explanation_holds(state):
    # The injunction is about out-of-season vegetables in Confucius's era;
    # it is meaningful only if they existed then. Other features do not enter.
    return state["oos_exists_in_era"]

results = {}
for key in options:
    fails_when_negated = False
    for oos, demanding, choice_now, mind in product([True, False], repeat=4):
        state = {
            "oos_exists_in_era": oos,
            "demanding": demanding,
            "choice_now": choice_now,
            "mind": mind,
        }
        negated = {
            "A": not state["demanding"],
            "B": not state["oos_exists_in_era"],
            "C": not state["choice_now"],
            "D": not state["mind"],
        }[key]
        if negated and not explanation_holds(state):
            fails_when_negated = True
    # necessary only if every state with the assumption negated breaks the explanation
    always_breaks = all(
        not explanation_holds({"oos_exists_in_era": o, "demanding": d,
                               "choice_now": c, "mind": m})
        for o, d, c, m in product([True, False], repeat=4)
        if {"A": not d, "B": not o, "C": not c, "D": not m}[key]
    )
    results[key] = always_breaks

necessary = [k for k, v in results.items() if v]
if len(necessary) == 1:
    print(json.dumps({"final_answer": necessary[0],
                      "evidence": {"necessary_by_negation_test": results,
                                   "option": options[necessary[0]]}}))
else:
    print("UNSUPPORTED")
