import json

def factorize(n):
    factors = {}
    d = 2
    m = n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

n = 33146799
f = factorize(n)

# verify product
prod = 1
for p, e in f.items():
    prod *= p ** e
assert prod == n

# verify primality of each factor by trial division
def is_prime(p):
    if p < 2:
        return False
    if p % 2 == 0:
        return p == 2
    i = 3
    while i * i <= p:
        if p % i == 0:
            return False
        i += 2
    return True

assert all(is_prime(p) for p in f)

primes = sorted(f)
expr = " * ".join(f"{p}^{e}" if e > 1 else str(p) for p, e in sorted(f.items()))

print(json.dumps({
    "final_answer": ", ".join(str(p) for p in primes),
    "evidence": {
        "n": n,
        "factorization": expr,
        "multiplicities": {str(p): e for p, e in sorted(f.items())},
        "product_check": prod == n,
    }
}))
