bikes = ["F", "G", "H", "J"]

def valid(d1, d2):
    for r in riders:
        if d1[r] == d2[r]:
            return False
    if "F" in (d1["R"], d2["R"]):
        return False
    if "J" in (d1["Y"], d2["Y"]):
        return False
    if "H" not in (d1["T"], d2["T"]):
        return False
    if d2["S"] != d1["Y"]:
        return False
    return True

sols = []
for p1 in itertools.permutations(bikes):
    d1 = dict(zip(riders, p1))
    if d1["T"] != "J":
        continue
    for p2 in itertools.permutations(bikes):
        d2 = dict(zip(riders, p2))
        if valid(d1, d2):
