def on_seg(p, a, b):
    cr = (b[0]-a[0])*(p[1]-a[1]) - (b[1]-a[1])*(p[0]-a[0])
    L = math.hypot(b[0]-a[0], b[1]-a[1])
    if L < 1e-9 or abs(cr)/L > EPS:
