    angs = [ang(j) for j in range(k)]
    def par(i, j):
        return abs(sides[i][0]*sides[j][1]-sides[i][1]*sides[j][0])/(lens[i]*lens[j]) < 1e-3
    eqlen = max(lens)-min(lens) < 1e-3*max(lens)
