from itertools import product

# Model: universe of size n, sets A and B as subsets (bitmasks).
def subsets(n):
    return range(1 << n)

def some_not(X, Y, n):   # some X are not Y
    return any(((X >> i) & 1) and not ((Y >> i) & 1) for i in range(n))

def not_all(X, Y, n):    # not all X are Y  (same truth condition as some X not Y)
    return not all((not ((X >> i) & 1)) or ((Y >> i) & 1) for i in range(n))

def valid(premise, conclusion, n=4):
    # exhaustive over all A,B subsets of a 4-element universe (finite check; counterexample suffices for invalidity)
    for A, B in product(subsets(n), repeat=2):
        if premise(A, B, n) and not conclusion(A, B, n):
            return False, (A, B)
    return True, None

# Original: Some A are not B => Not all B are A  (good-not-cheap => not all cheap are good)
orig = (lambda A, B, n: some_not(A, B, n), lambda A, B, n: not_all(B, A, n))

# Option forms (A = first-named subject class in the premise)
forms = {
    # A: Not all Hunan(H) like pepper(P) => some P are not H  : not_all(H,P) => some_not(P,H)
    "A": (lambda H, P, n: not_all(H, P, n), lambda H, P, n: some_not(P, H, n)),
    # B: Some people are not selfish => not all people are selfish: some_not(X,S) => not_all(X,S)
    "B": (lambda X, S, n: some_not(X, S, n), lambda X, S, n: not_all(X, S, n)),
    # C: good motive not necessarily good effect: some_not(M,E) => some good results not from good motives: some_not(E,M)
    "C": (lambda M, E, n: some_not(M, E, n), lambda M, E, n: some_not(E, M, n)),
    # D: some southerners not Cantonese => not all Cantonese are southerners: some_not(S,C) => not_all(C,S)
    "D": (lambda S, C, n: some_not(S, C, n), lambda S, C, n: not_all(C, S, n)),
}

v, ce = valid(*orig)
print("Original form valid?", v, "counterexample:", ce)
orig_valid = v

results = {}
for k, (p, c) in forms.items():
    vv, cex = valid(p, c)
    results[k] = vv
    print(f"Option {k}: valid={vv}, counterexample={cex}")

# Options sharing the original's (invalid) flawed form: all except the one that differs (valid form)
odd = [k for k, vv in results.items() if vv != orig_valid]
print("Option(s) whose form differs from original:", odd)

submitted = "C"
expected = odd[0] if len(odd) == 1 else None
print("Expected answer:", expected, "| Submitted:", submitted)
if expected == submitted:
    print("CHECK PASS")
else:
    print("CHECK FAIL")
