path = """M 0.0,16.81045 L 0.0,14.80251 M 0.0,0.0 L 0.0,14.80251 M -0.0,21.72644 L 0.0,16.81045 M -15.59808,14.80251 L -15.59808,21.72644 M -9.98277,8.80251 L 0.0,8.80251 M 9.07607,21.72644 L 9.07607,14.80251 M 5.35488,14.80251 L 0.0,14.80251 M -0.0,21.72644 L 9.07607,21.72644 M 0.0,14.80251 L -15.59808,14.80251 M -5.19615,11.80251 L 0.0,14.80251 M 0.0,8.80251 L -5.19615,11.80251 M -15.59808,21.72644 L -0.0,21.72644 M 9.07607,14.80251 L 9.07607,9.32558 M -15.59808,8.80251 L -9.98277,8.80251 M 9.07607,9.32558 L 9.07607,0.0 M 0.0,14.80251 L -0.0,21.72644 M 9.07607,14.80251 L 5.35488,14.80251 M -15.59808,14.80251 L -15.59808,13.48251 L -15.59808,8.80251 M 0.0,14.80251 L 9.07607,14.80251"""

toks = re.findall(r'[ML]|-?\d+\.?\d*', path)
segs = []
cur = None
i = 0
cmd = None
while i < len(toks):
    t = toks[i]
    if t in 'ML':
        cmd = t
        i += 1
        continue
    x = float(toks[i]); y = float(toks[i+1]); i += 2
    p = (round(x, 3) + 0.0, round(y, 3) + 0.0)
    if cmd == 'M':
        cur = p
    else:
        segs.append((cur, p))
        cur = p

pts = sorted({p for s in segs for p in s})
idx = {p: k for k, p in enumerate(pts)}

def on_seg(a, b, p, tol=2e-3):
    cr = (b[0]-a[0])*(p[1]-a[1]) - (b[1]-a[1])*(p[0]-a[0])
    L = math.hypot(b[0]-a[0], b[1]-a[1])
    if abs(cr)/L > tol:
        return False
    d = ((p[0]-a[0])*(b[0]-a[0]) + (p[1]-a[1])*(b[1]-a[1]))/L
    return -tol <= d <= L+tol

edges = set()
for a, b in segs:
    on = [p for p in pts if on_seg(a, b, p)]
    on.sort(key=lambda p: (p[0]-a[0])*(b[0]-a[0]) + (p[1]-a[1])*(b[1]-a[1]))
    for u, v in zip(on, on[1:]):
        if u != v:
            edges.add(frozenset((idx[u], idx[v])))

adj = {k: set() for k in range(len(pts))}
for e in edges:
    u, v = tuple(e)
    adj[u].add(v); adj[v].add(u)

cycles = set()
cyc_list = []
def dfs(start, node, path_):
    for nb in adj[node]:
        if nb == start and len(path_) >= 3:
            es = frozenset(frozenset((path_[j], path_[(j+1) % len(path_)])) for j in range(len(path_)))
            if es not in cycles:
                cycles.add(es); cyc_list.append(list(path_))
        elif nb > start and nb not in path_:
            dfs(start, nb, path_ + [nb])
for s in range(len(pts)):
    dfs(s, s, [s])

def cross(o, a, b):
    return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def inside(poly, p):
    c = False
    n = len(poly)
    for j in range(n):
        a = poly[j]; b = poly[(j+1) % n]
        if (a[1] > p[1]) != (b[1] > p[1]):
            xi = a[0] + (p[1]-a[1])*(b[0]-a[0])/(b[1]-a[1])
            if xi > p[0]:
                c = not c
    return c

def simplify(poly):
    res = poly[:]
    ch = True
    while ch and len(res) > 3:
        ch = False
        for j in range(len(res)):
            a = res[j-1]; b = res[j]; c = res[(j+1) % len(res)]
            if abs(cross(a, b, c)) < 5e-2:
                res.pop(j); ch = True; break
    return res

def close(a, b, r=2e-3):
    return abs(a-b) <= r*max(1, abs(a), abs(b))*5

def classify(P):
    n = len(P)
    sides = [math.hypot(P[(j+1) % n][0]-P[j][0], P[(j+1) % n][1]-P[j][1]) for j in range(n)]
    vec = [(P[(j+1) % n][0]-P[j][0], P[(j+1) % n][1]-P[j][1]) for j in range(n)]
    crs = [vec[j][0]*vec[(j+1) % n][1]-vec[j][1]*vec[(j+1) % n][0] for j in range(n)]
    convex = all(c > 0 for c in crs) or all(c < 0 for c in crs)
    def dot(j, k): return vec[j][0]*vec[k][0]+vec[j][1]*vec[k][1]
    def par(j, k): return abs(vec[j][0]*vec[k][1]-vec[j][1]*vec[k][0]) < 1e-2*sides[j]*sides[k]
    if n == 3:
        right = any(abs(dot(j, (j+1) % 3)) < 1e-2*sides[j]*sides[(j+1) % 3] for j in range(3))
        return 4 if right else 3
    if n == 4 and convex:
        p1 = par(0, 2); p2 = par(1, 3)
        if p1 and p2:
            rect = abs(dot(0, 1)) < 1e-2*sides[0]*sides[1]
            sq = rect and close(sides[0], sides[1])
            if sq: return 2
            if rect: return 1
            return 5
        if p1 != p2:
            return 6
        return None
    if n == 5:
        if not convex:
            return 8
        if all(close(s, sides[0]) for s in sides) and all(abs(c-crs[0]) < 1e-2*abs(crs[0]) for c in crs):
            return 9
        return 7
    if n == 6 and convex:
        if all(close(s, sides[0]) for s in sides) and all(abs(c-crs[0]) < 1e-2*abs(crs[0]) for c in crs):
            return 10
    return None

found = {}
for cyc in cyc_list:
    poly = [pts[k] for k in cyc]
    es = {frozenset((cyc[j], cyc[(j+1) % len(cyc)])) for j in range(len(cyc))}
    bad = False
    for e in edges:
        if e in es: continue
        u, v = tuple(e)
        m = ((pts[u][0]+pts[v][0])/2, (pts[u][1]+pts[v][1])/2)
        if inside(poly, m):
            bad = True; break
    if bad: continue
    for k in range(len(pts)):
        if k not in cyc and inside(poly, pts[k]):
            bad = True; break
    if bad: continue
    sp = simplify(poly)
    c = classify(sp)
    if c is not None:
        found.setdefault(c, []).append(sp)

for c in sorted(found):
    print("shape", c, "count", len(found[c]), found[c][0])
S = set(found)
