import json
from itertools import permutations

langs = {
    "South Korea": {"ko"},
    "France": {"fr", "de"},
    "Britain": {"en", "ko"},
    "Germany": {"ko", "fr", "en", "de"},
}
options = {
    "A": ["Britain", "Germany", "South Korea", "France"],
    "B": ["France", "Britain", "Germany", "South Korea"],
    "C": ["Germany", "Britain", "France", "South Korea"],
    "D": ["Germany", "Britain", "South Korea", "France"],
}

def comm(a, b):
    return bool(langs[a] & langs[b])

def valid(order):
    pos = {n: i for i, n in enumerate(order)}
    def nbrs(n):
        i = pos[n]
        return [order[j] for j in (i - 1, i + 1) if 0 <= j < 4]
    if not pos["South Korea"] > pos["Germany"]:
        return False
    if any(comm("South Korea", x) for x in nbrs("South Korea")):
        return False
    if any(comm("France", x) for x in nbrs("France")):
        return False
    if sum(comm("Britain", x) for x in nbrs("Britain")) != 1:
        return False
    return True

sols = [list(p) for p in permutations(langs) if valid(p)]
matching = [k for k, v in options.items() if v in sols]

if len(sols) == 1 and len(matching) == 1:
    print(json.dumps({
        "final_answer": matching[0],
        "evidence": {"valid_orders": sols, "matching_options": matching},
    }))
else:
    print("UNSUPPORTED")
