```python
from itertools import permutations

langs = {"K": {"Ko"}, "F": {"Fr", "Ge"}, "B": {"En", "Ko"}, "G": {"Ko", "Fr", "En", "Ge"}}
names = {"K": "South Korea", "F": "France", "B": "Britain", "G": "Germany"}

def comm(a, b):
    return bool(langs[a] & langs[b])

def neighbors(order, i):
    return [order[j] for j in (i - 1, i + 1) if 0 <= j < 4]

def valid(order):
    pos = {n: i for i, n in enumerate(order)}
    # Korean room number larger than German
    if not pos["K"] > pos["G"]:
        return False
    # Korean can't communicate with any neighbor
    if any(comm("K", n) for n in neighbors(order, pos["K"])):
        return False
    # French can't communicate with any neighbor
    if any(comm("F", n) for n in neighbors(order, pos["F"])):
        return False
    # British communicates with exactly one neighbor
    if sum(comm("B", n) for n in neighbors(order, pos["B"])) != 1:
        return False
    # German speaks all four languages
    if langs["G"] != {"Ko", "Fr", "En", "Ge"}:
        return False
    return True

options = {
    "A": ["B", "G", "K", "F"],
    "B": ["F", "B", "G", "K"],
    "C": ["G", "B", "F", "K"],
    "D": ["G", "B", "K", "F"],
}

solutions = [p for p in permutations("KFBG") if valid(p)]
print("All valid orderings:", [[names[x] for x in s] for s in solutions])

for k, v in options.items():
    print(k, [names[x] for x in v], "valid" if valid(v) else "invalid")

submitted = options["D"]
if valid(submitted) and len(solutions) == 1:
    print("CHECK PASS")
else:
    print("CHECK FAIL: submitted option D is not consistent with the statements")
